MAX_ATTEMPTS = 4
BACKOFF = (1, 2, 4)  # waits before attempts 2, 3 and 4
_SERVER_ERRORS = (500, 502, 503, 504)


def _error(r: Response) -> ApiError:
    try:
        code = str(json.loads(r.body)["error"]["code"])
    except (ValueError, KeyError, TypeError):
        code = ""
    return ApiError(r.status, code)


def _key(operation: str, reference: str) -> str:
    return f"pl-{operation}-{hashlib.sha256(reference.encode('utf-8')).hexdigest()[:24]}"


def _wait(transport: Transport, failed_attempt: int, r: Response | None) -> None:
    """Waits before the attempt following `failed_attempt` (1-based)."""
    seconds: float = BACKOFF[failed_attempt - 1]
    if r is not None:
        for name, value in r.headers.items():
            if name.lower() == "retry-after":
                try:
                    seconds = int(str(value).strip())
                except ValueError:
                    pass
                break
    transport.sleep(seconds)


def _retryable(r: Response) -> bool:
    if r.status in _SERVER_ERRORS or r.status == 429:
        return True
    return r.status == 409 and _error(r).code == "idempotency_in_progress"


def _call(
    transport: Transport,
    method: str,
    path: str,
    body: dict[str, Any] | None = None,
    key: str | None = None,
) -> Any:
    headers = {} if key is None else {"Idempotency-Key": key}
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            r = transport.send(method, path, dict(headers), body)
        except ConnectionError:
            if attempt == MAX_ATTEMPTS:
                raise
            _wait(transport, attempt, None)
            continue
        if r.status in (200, 201):
            return json.loads(r.body)
        if attempt < MAX_ATTEMPTS and _retryable(r):
            _wait(transport, attempt, r)
            continue
        raise _error(r)
    raise AssertionError("unreachable")

path = f"{BASE}/transfers/{transfer_id}/reversal"
for attempt in range(1, MAX_ATTEMPTS + 1):
    # A reversal takes no key and is not idempotent: after an ambiguous failure, check
    # whether it was applied before sending it again.
    try:
        r = transport.send("POST", path, {}, None)
    except ConnectionError:
        if attempt == MAX_ATTEMPTS:
            raise
        _wait(transport, attempt, None)
        if (t := _transfer(_call(transport, "GET", f"{BASE}/transfers/{transfer_id}"))).status == "reversed":
            return t
        continue
    if r.status in (200, 201):
        return _transfer(json.loads(r.body))
    if attempt < MAX_ATTEMPTS and (r.status == 429 or r.status in _SERVER_ERRORS):
        _wait(transport, attempt, r)
        if r.status != 429:
            t = _transfer(_call(transport, "GET", f"{BASE}/transfers/{transfer_id}"))
            if t.status == "reversed":
                return t
        continue
    raise _error(r)
raise AssertionError("unreachable")

